-- Curated ingredient seed data, generated from supabase/seed/ingredients-seed.ts.
-- Run this in the Supabase SQL Editor AFTER applying supabase/schema.sql.
-- Safe to re-run: upserts by canonical_name.
-- (No terminal/service-role key needed — this is a plain SQL alternative to
-- `npm run seed` for setups where running a local Node script isn't an option.)

on conflict (canonical_name) do update set
  inci_name = excluded.inci_name,
  aliases = excluded.aliases,
  category = excluded.category,
  comedogenic_rating = excluded.comedogenic_rating,
  irritancy_rating = excluded.irritancy_rating,
  benefit_score = excluded.benefit_score,
  skin_type_fit = excluded.skin_type_fit,
  description = excluded.description,
  is_rated = excluded.is_rated,
  source = excluded.source,
  updated_at = now();
